import vitest from "ultracite/oxlint/vitest";

const siteReact = {
  ...react,
  rules: {
    ...react.rules,
    // Effect Match and Option callbacks return JSX inline but do not define
    // stateful React components. Keep the rule for actual nested components.
    "react/no-unstable-nested-components": ["error", { allowAsProps: true }],
  },
};

const siteVitest = {
  ...vitest,
  overrides: vitest.overrides?.map((override) => ({
    ...override,
    rules: {
      ...override.rules,
      // Keep cohesive contract tests bounded without Ultracite's generic
      // five-assertion default splitting one lifecycle across many tests.
      "vitest/max-expects": ["error", { max: 20 }],
    },
  })),
};

