import { Schema } from "effect";
import type { Context } from "effect";

import { DateInterval } from "../primitives/date.js";
import type { SourceArtifact, SourceRef } from "../trace/node.js";

/**
 * Stable identifier for an official parameter service.
 *
 * @since 0.1.0
 */
export const ParameterId = Schema.String.pipe(
  Schema.brand("taxkit/ParameterId")
);

/**
 * Stable identifier for an official parameter service.
 *
 * @since 0.1.0
 */
export type ParameterId = typeof ParameterId.Type;

/**
 * Date range in which a parameter descriptor is valid.
 *
 * The interval is half-open: `[from, toExclusive)`. Date-level precision is
 * required because official tax changes can start mid-year.
 *
 * @since 0.1.0
 */
export const ParameterEffectivePeriod = DateInterval;

/**
 * Date range in which a parameter descriptor is valid.
 *
 * @since 0.1.0
 */
export type ParameterEffectivePeriod = typeof ParameterEffectivePeriod.Type;

/**
 * Static metadata for a sourced parameter service supplied to rule layers.
 *
 * Parameter descriptors let graph validation tie a rule's required parameter
 * services back to the source references that justify them.
 *
 * @since 0.1.0
 */
export interface ParameterDescriptor<Self, Shape> {
  readonly effectivePeriod: ParameterEffectivePeriod;
  readonly id: ParameterId;
  readonly schema: Schema.Schema<Shape>;
  readonly source: SourceRef;
  readonly sourceArtifact?: SourceArtifact;
  readonly tag: Context.Key<Self, Shape>;
  readonly title: string;
}

/**
 * Parameter descriptor with its service type erased for graph validation.
 *
 * @since 0.1.0
 */
export type AnyParameterDescriptor = ParameterDescriptor<unknown, unknown>;

/**
 * Builds a schema-backed parameter descriptor with a branded stable ID.
 *
 * @since 0.1.0
 */
export const makeParameterDescriptor = <Self, Shape>(args: {
  readonly effectivePeriod: ParameterEffectivePeriod;
  readonly id: string;
  readonly schema: Schema.Schema<Shape>;
  readonly source: SourceRef;
  readonly sourceArtifact?: SourceArtifact;
  readonly tag: Context.Key<Self, Shape>;
  readonly title: string;
}): ParameterDescriptor<Self, Shape> => ({
  effectivePeriod: ParameterEffectivePeriod.make(args.effectivePeriod),
  id: ParameterId.make(args.id),
  schema: args.schema,
  source: args.source,
  ...(args.sourceArtifact === undefined
    ? {}
    : { sourceArtifact: args.sourceArtifact }),
  tag: args.tag,
  title: args.title,
});
import { Schema } from "effect";
import type { Context } from "effect";

/**
 * Stable identifier for a fact produced or consumed by rules.
 *
 * @since 0.1.0
 */
export const FactId = Schema.String.pipe(Schema.brand("taxkit/FactId"));

/**
 * Stable identifier for a fact produced or consumed by rules.
 *
 * @since 0.1.0
 */
export type FactId = typeof FactId.Type;

/**
 * Declares where a fact is expected to come from in a calculation graph.
 *
 * @since 0.1.0
 */
export const FactAuthority = Schema.Literals(["input", "derived", "parameter"]);

/**
 * Declares where a fact is expected to come from in a calculation graph.
 *
 * @since 0.1.0
 */
export type FactAuthority = typeof FactAuthority.Type;

/**
 * Stable identifier for a caller-facing fact question.
 *
 * @since 0.1.0
 */
export const FactQuestionId = Schema.String.pipe(
  Schema.brand("taxkit/FactQuestionId")
);

/**
 * Stable identifier for a caller-facing fact question.
 *
 * @since 0.1.0
 */
export type FactQuestionId = typeof FactQuestionId.Type;

/**
 * Input control category needed to collect an input fact.
 *
 * @since 0.1.0
 */
export const FactQuestionInputKind = Schema.Literals([
  "money",
  "boolean",
  "selection",
]);

/**
 * Input control category needed to collect an input fact.
 *
 * @since 0.1.0
 */
export type FactQuestionInputKind = typeof FactQuestionInputKind.Type;

/**
 * Caller-facing metadata for an input fact without coupling core to a UI.
 *
 * @since 0.1.0
 */
export class FactQuestion extends Schema.TaggedClass<FactQuestion>()(
  "FactQuestion",
  {
    helpText: Schema.optional(Schema.String),
    id: FactQuestionId,
    inputKind: FactQuestionInputKind,
    prompt: Schema.String,
  }
) {}

/**
 * Static metadata for a fact service in a rule graph.
 *
 * Descriptors are used by graph validation, docs generation, source review,
 * and caller question planning. The descriptor must match the actual
 * `Context.Service` tag supplied or derived by rule layers.
 *
 * @since 0.1.0
 */
export interface FactDescriptor<Self, Shape> {
  readonly id: FactId;
  readonly title: string;
  readonly authority: FactAuthority;
  readonly schema: Schema.Schema<Shape>;
  readonly tag: Context.Key<Self, Shape>;
  readonly question?: FactQuestion;
}

/**
 * Builds a schema-backed fact descriptor with a branded stable ID.
 * @since 0.1.0
 */
export const makeFactDescriptor = <Self, Shape>(args: {
  readonly id: string;
  readonly title: string;
  readonly authority: FactAuthority;
  readonly schema: Schema.Schema<Shape>;
  readonly tag: Context.Key<Self, Shape>;
  readonly question?: FactQuestion;
}): FactDescriptor<Self, Shape> => ({
  authority: args.authority,
  id: FactId.make(args.id),
  schema: args.schema,
  tag: args.tag,
  title: args.title,
  ...(args.question === undefined ? {} : { question: args.question }),
});
import { Schema } from "effect";

import { IsoDate } from "../primitives/date.js";
import { RoundingMode } from "../primitives/rounding.js";

/**
 * Stable identifier for the rule that produced a trace node.
 *
 * @since 0.1.0
 */
export const RuleId = Schema.String.pipe(Schema.brand("taxkit/RuleId"));

/**
 * Stable identifier for the rule that produced a trace node.
 *
 * @since 0.1.0
 */
export type RuleId = typeof RuleId.Type;

/**
 * Kind of authority referenced by a rule or parameter source.
 *
 * @since 0.1.0
 */
export const SourceKind = Schema.Literals([
  "ato-publication",
  "legislation",
  "regulation",
  "internal-validation",
]);

/**
 * Kind of authority referenced by a rule or parameter source.
 *
 * @since 0.1.0
 */
export type SourceKind = typeof SourceKind.Type;

/**
 * A source citation that justifies a rule or parameter value.
 * @since 0.1.0
 */
export const SourceRef = Schema.TaggedStruct("SourceRef", {
  kind: SourceKind,
  reference: Schema.String,
  title: Schema.String,
});

/**
 * A source citation that justifies a rule or parameter value.
 *
 * @since 0.1.0
 */
export type SourceRef = typeof SourceRef.Type;

/**
 * Stable checksum for an extracted official source artifact.
 *
 * @since 0.1.0
 */
export const SourceChecksum = Schema.String.pipe(
  Schema.brand("taxkit/SourceChecksum")
);

/**
 * Stable checksum for an extracted official source artifact.
 *
 * @since 0.1.0
 */
export type SourceChecksum = typeof SourceChecksum.Type;

/**
 * Metadata for the extracted rows used by a parameter table.
 *
 * @since 0.1.0
 */
export class SourceExtract extends Schema.TaggedClass<SourceExtract>()(
  "SourceExtract",
  {
    rowCount: Schema.Int,
    shape: Schema.String,
  }
) {}

/**
 * Canonical audit record for official parameter data.
 *
 * @since 0.1.0
 */
export class SourceArtifact extends Schema.TaggedClass<SourceArtifact>()(
  "SourceArtifact",
  {
    checksum: SourceChecksum,
    documentVersion: Schema.String,
    extract: SourceExtract,
    retrievedOn: IsoDate,
    source: SourceRef,
  }
) {}

/**
 * Brands a source artifact checksum.
 *
 * @since 0.1.0
 */
export const sourceChecksum = (value: string): SourceChecksum =>
  SourceChecksum.make(value);

/**
 * Explanation tree for a calculated value.
 *
 * @since 0.1.0
 */
export interface TraceNode {
  readonly _tag: "TraceNode";
  readonly ruleId: RuleId;
  readonly title: string;
  readonly inputs: Readonly<Record<string, unknown>>;
  readonly formula?: string | undefined;
  readonly result: unknown;
  readonly rounding?: RoundingMode | undefined;
  readonly sources: readonly SourceRef[];
  readonly children: readonly TraceNode[];
}

/**
 * Encoded representation of a trace node for persistence or transport.
 *
 * @since 0.1.0
 */
export interface TraceNodeEncoded {
  readonly _tag: "TraceNode";
  readonly ruleId: string;
  readonly title: string;
  readonly inputs: Readonly<Record<string, unknown>>;
  readonly formula?: string | undefined;
  readonly result: unknown;
  readonly rounding?: typeof RoundingMode.Encoded | undefined;
  readonly sources: readonly (typeof SourceRef.Encoded)[];
  readonly children: readonly TraceNodeEncoded[];
}

/**
 * Recursive schema codec for calculation trace nodes.
 *
 * @since 0.1.0
 */
export const TraceNode: Schema.Codec<TraceNode, TraceNodeEncoded> =
  Schema.TaggedStruct("TraceNode", {
    children: Schema.Array(
      Schema.suspend((): Schema.Codec<TraceNode, TraceNodeEncoded> => TraceNode)
    ),
    formula: Schema.optional(Schema.String),
    inputs: Schema.Record(Schema.String, Schema.Unknown),
    result: Schema.Unknown,
    rounding: Schema.optional(RoundingMode),
    ruleId: RuleId,
    sources: Schema.Array(SourceRef),
    title: Schema.String,
  });
import { Context } from "effect";
import type { Effect } from "effect";

import type {
  CalculatorCatalogItem,
